// 永久消费凭据完整保原出生、会话与本人say；解码只核形状，真实来源必须再走具名只读。
#include "born_personal_dialogue_proof_codec.hpp"
#include "resident/domains/tasks/task_dynamic_codec.hpp"
#include <set>
namespace hanmo::resident {namespace {
template<class A>Status identity(A& a,WorldIdentity& v){std::vector<Integer> bytes;if(a.reading())a.sequence("world_id",bytes,[](auto&c,auto&b){return c.field("byte",b);});else a.write_sequence("world_id",v.world_id,[](auto&c,const auto&raw){Integer b=raw;return c.field("byte",b);});if(a.reading()&&a.status().ok){if(bytes.size()!=16)return a.reject("InvalidBornPersonalDialogueWorld");for(std::size_t i=0;i<16;++i){if(bytes[i]<0||bytes[i]>255)return a.reject("InvalidBornPersonalDialogueWorld");v.world_id[i]=static_cast<std::uint8_t>(bytes[i]);}}a.field("execution_epoch",v.execution_epoch);a.field("revision",v.revision);return a.field("tick",v.tick);}
template<class A>Status context(A& a,InteractionContext& c){a.field("place_id",c.place_id);a.field("provider_actor_id",c.provider_actor_id);a.field("role_id",c.role_id);a.optional("kind",c.kind,[](auto& x,auto& v){return x.field("value",v);});a.optional("encounter_id",c.encounter_id,[](auto& x,auto& v){return x.field("value",v);});return a.optional("input_error",c.input_error,[](auto& x,auto& v){return x.field("value",v);});}
template<class A>Status proof(A& a,BornPersonalDialogueProof& p){a.field("opening_fact_id",p.opening_fact_id);a.field("template_id",p.template_id);a.object("declaration",[&](auto& c){c.field("speaker_actor_id",p.declaration.speaker_actor_id);return c.object("meeting",[&](auto& x){auto& m=p.declaration.meeting;x.object("source_identity",[&](auto& y){return identity(y,m.source_identity);});x.field("actor_id",m.actor_id);x.field("provider_actor_id",m.provider_actor_id);x.field("session_id",m.session_id);x.field("dialogue_id",m.dialogue_id);x.field("node_id",m.node_id);x.field("node_kind",m.node_kind);return x.object("context",[&](auto& y){return context(y,m.context);});});});return a.object("born",[&](auto& c){auto& b=p.born;c.object("source_identity",[&](auto& y){return identity(y,b.source_identity);});c.field("actor_id",b.actor_id);c.field("birth_fact_id",b.birth_fact_id);c.field("creation_fact_id",b.creation_fact_id);c.field("prototype_id",b.prototype_id);c.field("before_fact_id",b.before_fact_id);dynamic_codec::strings(c,"biological_parent_ids",b.biological_parent_ids);c.field("birth_tick",b.birth_tick);c.field("observed_tick",b.observed_tick);c.field("adult",b.adult);return c.field("alive",b.alive);});}
Status unique(const BoundaryValue& v,std::size_t depth=0){if(depth>CodecVisitor::max_depth)return common_failure("BornPersonalDialogueProofTooDeep");if(const auto* d=v.as<BoundaryValue::Dict>()){if(d->size()>CodecVisitor::max_items)return common_failure("BornPersonalDialogueProofTooLarge");std::set<StableId> keys;for(const auto& row:*d){if(!keys.insert(row.first).second)return common_failure("DuplicateBornPersonalDialogueProofField",row.first);auto r=unique(row.second,depth+1);if(!r.ok)return r;}}if(const auto* a=v.as<BoundaryValue::Array>()){if(a->size()>CodecVisitor::max_items)return common_failure("BornPersonalDialogueProofTooLarge");for(const auto& row:*a){auto r=unique(row,depth+1);if(!r.ok)return r;}}return common_success();}
}
Status emit_born_personal_dialogue_proof_fields(ProjectionWriter&w,const BornPersonalDialogueProof&p){DynamicProjectionArchive a(w);return proof(a,const_cast<BornPersonalDialogueProof&>(p));}
BoundaryValue encode_born_personal_dialogue_proof(const BornPersonalDialogueProof&p){BoundaryValue value;BoundaryProjectionWriter w(value);auto r=w.object("",[&](auto&out){return emit_born_personal_dialogue_proof_fields(out,p);});if(r.ok)r=w.finish();if(!r.ok){boundary::DecodeFailure failure(r.error.original.code,r.error.original.path);failure.error=r.error;throw failure;}return value;}
Outcome<BornPersonalDialogueProof> decode_born_personal_dialogue_proof(const BoundaryValue& v){auto r=unique(v);if(!r.ok)return {false,{},r.error};BornPersonalDialogueProof p;dynamic_codec::JsonArchive a(v);r=proof(a,p);if(r.ok)r=a.finish();return r.ok?Outcome<BornPersonalDialogueProof>{true,std::move(p),{}}:Outcome<BornPersonalDialogueProof>{false,{},r.error};}
Status visit_born_personal_dialogue_proof(CodecVisitor& a,BornPersonalDialogueProof& p){return proof(a,p);}
Status visit_born_personal_dialogue_proof(DynamicProjectionArchive&a,BornPersonalDialogueProof&p){return proof(a,p);}
Status visit_born_personal_dialogue_proof(dynamic_codec::JsonArchive&a,BornPersonalDialogueProof&p){return proof(a,p);}

}
